ep = w3.eth.contract(address=ENTRY_POINT, abi=EP_ABI)

def pack(a, b) -> bytes:
    v1 = int(a, 16) if isinstance(a, str) else a
    v2 = int(b, 16) if isinstance(b, str) else b
    return v1.to_bytes(16, "big") + v2.to_bytes(16, "big")

def userOpHash(smart_account, nonce, call_data, vgl, cgl, pvg, mpf, mxf) -> str:
    op = {
        "sender": smart_account, "nonce": nonce,
        "initCode": b"", "callData": call_data,
        "accountGasLimits": pack(vgl, cgl),
        "preVerificationGas": pvg,
        "gasFees": pack(mpf, mxf),
        "paymasterAndData": b"", "signature": b""
    }
    h = ep.functions.getUserOpHash(op).call()
    return h

def estGas(companyAccount: str, inner_data: bytes, signerAddr: str):
    companyAcc = Web3.to_checksum_address(companyAccount)
    sel = Web3.keccak(text="execute(address,uint256,bytes,address)")[:4]
    exec_data = sel + w3.codec.encode(["address", "uint256", "bytes", "address"], [REGISTRY, 0, inner_data, signerAddr])
    nonce = ep.functions.getNonce(companyAcc, 0).call()
    fees  = Web3.to_wei(10, "gwei")
    DUMMY_SIG = "0x" + "1b" * 65

    op = {
        "sender":               companyAcc,
        "nonce":                hex(nonce),
        "callData":             "0x" + exec_data.hex(),
        "callGasLimit":         hex(500_000),
        "verificationGasLimit": hex(500_000),
        "preVerificationGas":   hex(100_000),
        "maxFeePerGas":         hex(fees),
        "maxPriorityFeePerGas": hex(fees),
        "signature":            DUMMY_SIG,
    }

    resp = requests.post(BUNDLER_URL, json={"jsonrpc":"2.0","id":1,"method":"eth_estimateUserOperationGas","params":[{
            "sender": companyAcc, "nonce": hex(nonce), "callData": "0x" + exec_data.hex(),
            "maxFeePerGas": hex(fees), "maxPriorityFeePerGas": hex(fees), "signature": DUMMY_SIG,}, ENTRY_POINT]}).json()
    if "error" in resp: 
        raise ValueError(f"Estimation Error: {resp['error']}")

    est = resp["result"]
    vgl, cgl, pvg = int(est["verificationGasLimit"], 16), int(est["callGasLimit"], 16), int(est["preVerificationGas"], 16)
    print(f"gas: vgl={vgl} cgl={cgl} pvg={pvg}")

    op["verificationGasLimit"] = hex(vgl)
    op["callGasLimit"] = hex(cgl)
    op["preVerificationGas"] = hex(pvg)

    userHash = userOpHash(companyAcc, nonce, exec_data, vgl, cgl, pvg, fees, fees)
    return op, userHash


def sendUserOp(op: dict):
    print("\neth_sendUserOperation")
    res = requests.post(BUNDLER_URL, json={
        "jsonrpc": "2.0", "id": 1,
        "method": "eth_sendUserOperation",
        "params": [op, ENTRY_POINT],
    }, timeout=30).json()

    if "error" in res:
        raise ValueError(f"Send error: {res['error']}")

    op_hash_hex = res["result"]
    print(f"  Sent! UserOp hash: {op_hash_hex}")

    print("  Waiting for receipt", end="", flush=True)
    for _ in range(40):
        time.sleep(3)
        r = requests.post(BUNDLER_URL, json={
            "jsonrpc": "2.0", "id": 2,
            "method": "eth_getUserOperationReceipt",
            "params": [op_hash_hex],
        }, timeout=30).json().get("result")
        if r:
            print(f"\n  Mined! tx: {r['receipt']['transactionHash']}")
            break
        print(".", end="", flush=True)
    else:
        print(f"\n  Timeout waiting for {op_hash_hex}")
    return op_hash_hex

